// FR-WLD-15: the themes config/themes/ ships, as generated by `just tokens`. `themeFor` is the one place a stored
// or typed theme id becomes the `data-theme` of the Park root: anything unknown is the default (Studio, UI-STUDIO-1).
import { DEFAULT_THEME, THEMES } from "./themes.generated";

export { DEFAULT_THEME, THEMES };

export function themeFor(pref: unknown): string {
  return THEMES.find((t) => t.id === pref)?.id ?? DEFAULT_THEME;
}
